  3→import (
  4→	"fmt"
  5→
  6→	"github.com/finalappstore/stupidsamba/internal/smb/crypto"
  7→	"github.com/finalappstore/stupidsamba/internal/smb/status"
  8→	"github.com/finalappstore/stupidsamba/internal/smb/wire"
  9→)
 10→
 11→// Handler 处理一条 SMB2 请求。
 12→//
 13→// 约定：
 14→//   - 成功时把**报文体**追加到 ctx.Out（响应头已由分发器预置），返回 nil；
 15→//   - 失败时返回 error。返回 status.Status 可以精确指定 NTSTATUS，
 16→//     返回其它错误由 status.FromVFSError 统一映射（AGENTS.md §5 P5，
 17→//     禁止在 handler 里裸写魔数）。
 18→//   - 需要返回带响应体的非 SUCCESS 状态（如 SESSION_SETUP 的
 19→//     STATUS_MORE_PROCESSING_REQUIRED、QUERY_INFO 的 STATUS_BUFFER_OVERFLOW）时，
 20→//     直接设置 ctx.Status 并返回 nil。
 21→type Handler func(ctx *Context) error
 22→
 23→// handlerSpec 描述一个命令的处理器及其前置条件。
 24→type handlerSpec struct {
 25→	fn Handler
 26→	// needSession 表示必须有一个**已认证**的会话。
 27→	needSession bool
 28→	// needTree 表示必须有一个有效的树连接。
 29→	needTree bool
 30→}
 31→
 32→// handlers 是命令分发表（AGENTS.md §5 P2 策略模式）。
 33→//
 34→// 新增一个命令只需要在自己的文件里 init() 调 register()，
 35→// **不需要改动本文件**。未注册的命令统一走 defaultHandler。
 36→var handlers = map[wire.Command]handlerSpec{}
 37→
 38→// register 登记一个命令处理器。重复注册会 panic —— 这是编码错误，
 39→// 发生在进程启动阶段（init），不会影响运行中的服务。
 40→func register(cmd wire.Command, needSession, needTree bool, fn Handler) {
 41→	if _, dup := handlers[cmd]; dup {
 42→		panic(fmt.Sprintf("command: %s 重复注册", cmd))
 43→	}
 44→	handlers[cmd] = handlerSpec{fn: fn, needSession: needSession, needTree: needTree}
 45→}
 46→
 47→// Registered 报告某个命令是否已经实现，用于日志与测试。
 48→func Registered(cmd wire.Command) bool {
 49→	_, ok := handlers[cmd]
 50→	return ok
 51→}
 52→
 53→// defaultHandler 处理所有未实现的命令（AGENTS.md §5 P2）。
 54→func defaultHandler(ctx *Context) error {
 55→	ctx.Log.Debug("未实现的 SMB2 命令", "command", ctx.Header.Command.String(),
 56→		"remote", ctx.Conn.RemoteAddr)
 57→	return status.NotSupported
 58→}
 59→
 60→// Dispatch 处理一条请求并把响应写入 ctx.Out。
 61→//
 62→// 无论成功失败都会产生一条格式正确的响应 —— SMB2 不允许对请求静默不答，
 63→// 客户端会一直等到超时。
 64→func Dispatch(ctx *Context) {
 65→	err := dispatch(ctx)
 66→	if err != nil {
 67→		ctx.fail(status.FromVFSError(err))
 68→	}
 69→	ctx.finishHeader()
 70→
 71→	// 把本条解析/新建出的会话与树记入链，供后续 related 消息继承。
 72→	if ctx.Session != nil {
 73→		ctx.Chain.Session = ctx.Session
 74→	}
 75→	if ctx.Tree != nil {
 76→		ctx.Chain.Tree = ctx.Tree
 77→	}
 78→
 79→	// 只有 handler **真的失败**才中断复合链。
 80→	// 带响应体的非 SUCCESS 状态（SESSION_SETUP 的 MORE_PROCESSING_REQUIRED、
 81→	// QUERY_INFO 的 BUFFER_OVERFLOW）不算失败，后续 related 消息照常执行。
 82→	if err != nil {
 83→		ctx.Chain.Failed = true
 84→		if ctx.Chain.FailStatus == 0 {
 85→			ctx.Chain.FailStatus = ctx.Status
 86→		}
 87→	}
 88→}
 89→
 90→// DispatchFailed 在前置检查（如签名校验）就已经判定失败时，
 91→// 直接产生一条 ERROR Response 并回填响应头。
 92→//
 93→// 与 Dispatch 一样，它保证一定会写出一条格式正确的响应。
 94→func DispatchFailed(ctx *Context, st status.Status) {
 95→	ctx.fail(st)
 96→	ctx.finishHeader()
 97→	ctx.Chain.Failed = true
 98→	if ctx.Chain.FailStatus == 0 {
 99→		ctx.Chain.FailStatus = st
100→	}
101→}
102→
103→// dispatch 执行前置检查与 handler。
104→func dispatch(ctx *Context) error {
105→	// 复合链中前序已失败：后续 related 消息必须直接失败，不得执行
106→	// （MS-SMB2 §3.3.5.2.7）。
107→	if ctx.Header.IsRelated() && ctx.Chain.Failed {
108→		st := ctx.Chain.FailStatus
109→		if st == 0 {
110→			st = status.Unsuccessful
111→		}
112→		return st
113→	}
114→
115→	spec, ok := handlers[ctx.Header.Command]
116→	if !ok {
117→		spec = handlerSpec{fn: defaultHandler}
118→	}
119→
120→	// 先定位会话与树（含 related 继承），再校验签名 —— 验签需要会话密钥。
121→	if err := ctx.resolve(); err != nil {
122→		return err
123→	}
124→	if err := ctx.checkSignature(); err != nil {
125→		return err
126→	}
127→
128→	if spec.needSession {
129→		if ctx.Session == nil {
130→			return status.UserSessionDeleted
131→		}
132→		if !ctx.Session.Established() {
133→			return status.AccessDenied
134→		}
135→	}
136→	if spec.needTree && ctx.Tree == nil {
137→		return status.NetworkNameDeleted
138→	}
139→
140→	return spec.fn(ctx)
141→}
142→
143→// resolve 根据请求头定位会话与树，并处理复合链里的继承语义。
144→//
145→// MS-SMB2 §3.3.5.2.7：置了 SMB2_FLAGS_RELATED_OPERATIONS 的消息复用
146→// 前一条的 SessionId / TreeId，头里的对应字段应当被忽略。
147→func (c *Context) resolve() error {
148→	if c.Header.IsRelated() {
149→		c.Session = c.Chain.Session
150→		c.Tree = c.Chain.Tree
151→		// 响应头要回填真实的 Id，客户端据此对账。
152→		if c.Session != nil {
153→			c.RespHeader.SessionID = c.Session.ID
154→		}
155→		if c.Tree != nil {
156→			c.RespHeader.TreeID = c.Tree.ID
157→		}
158→		return nil
159→	}
160→
161→	if id := c.Header.SessionID; id != 0 {
162→		s := c.Conn.Session(id)
163→		if s == nil {
164→			// MS-SMB2 §3.3.5.2.9：找不到会话回 STATUS_USER_SESSION_DELETED。
165→			return status.UserSessionDeleted
166→		}
167→		c.Session = s
168→		c.Chain.Session = s
169→	}
170→
171→	if id := c.Header.TreeID; id != 0 {
172→		if c.Session == nil {
173→			return status.UserSessionDeleted
174→		}
175→		t := c.Session.Tree(id)
176→		if t == nil {
177→			// MS-SMB2 §3.3.5.2.11：找不到树回 STATUS_NETWORK_NAME_DELETED。
178→			return status.NetworkNameDeleted
179→		}
180→		c.Tree = t
181→		c.Chain.Tree = t
182→	}
183→	return nil
184→}
185→
186→// checkSignature 校验请求签名，并决定响应是否需要签名。
187→//
188→// MS-SMB2 §3.3.5.2.4：
189→//   - 请求置了 SMB2_FLAGS_SIGNED 且会话已建立 → 必须验签，失败回
190→//     STATUS_ACCESS_DENIED；
191→//   - 会话要求签名而请求没签 → STATUS_ACCESS_DENIED；
192→//   - 验签通过的请求，其响应也必须签名。
193→//
194→// SESSION_SETUP 是例外：认证完成前还没有会话密钥，签名由该命令的 handler
195→// 在密钥派生之后自行处理（§3.3.5.5.3）。
196→func (c *Context) checkSignature() error {
197→	if c.Header.Command == wire.CommandSessionSetup {
198→		return nil
199→	}
200→
201→	s := c.Session
202→	if s == nil || !s.Established() {
203→		return nil
204→	}
205→
206→	key := s.SigningKey()
207→	signed := c.Header.IsSigned()
208→
209→	if !signed {
210→		if s.SigningRequired() {
211→			c.Log.Warn("会话要求签名但请求未签名",
212→				"command", c.Header.Command.String(), "session", s.ID)
213→			return status.AccessDenied
214→		}
215→		return nil
216→	}
217→
218→	if len(key) == 0 {
219→		// 客户端声称签了名，但我们没有密钥可校验 —— 只能拒绝。
220→		return status.AccessDenied
221→	}
222→	if err := crypto.VerifyWith(c.Conn.SigningAlg(), key, c.Msg); err != nil {
223→		c.Log.Warn("请求签名校验失败",
224→			"command", c.Header.Command.String(), "session", s.ID, "err", err)
225→		return status.AccessDenied
226→	}
227→
228→	// 验签通过：响应也要签名。实际计算由 internal/server 在复合链拼装完成
229→	// 之后统一执行（签名范围含尾部对齐填充）。
230→	c.SignKey = key
231→	return nil
232→}
233→
234→// fail 丢弃已写入的响应体，改写成一条 SMB2 ERROR Response。
235→func (c *Context) fail(st status.Status) {
236→	if st == status.Success {
237→		st = status.Unsuccessful
238→	}
239→	c.ResetBody()
240→	c.Status = st
241→
242→	// MS-SMB2 §2.2.2：ByteCount 为 0 时 ErrorData 必须补 1 字节占位，
243→	// 这由 wire.ErrorResponse.Append 负责。
244→	out, err := (&wire.ErrorResponse{}).Append(c.Out)
245→	if err != nil {
246→		// ErrorResponse 是定长结构，编码不可能失败；真出错也不能让连接静默，
247→		// 保底写一条最小 ERROR body。
248→		c.Log.Error("编码 ERROR Response 失败", "err", err)
249→		c.ResetBody()
250→		c.Out = append(c.Out, 0x09, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00)
251→		return
252→	}
253→	c.Out = out
254→}
