	if spec, ok := handlers[ctx.Header.Command]; ok && spec.noResponse {
		_ = spec.fn(ctx)
		ctx.suppress = true
		ctx.discard()
		return
	}

	err := dispatch(ctx)
	if err != nil {
		ctx.fail(status.FromVFSError(err))
